#include "memo_file.h"
#include <cstring>
#include <fstream>

bool saveMemoFile(const std::string& path, const MemoFileHeader& hdr, const MemoTable& t){ std::ofstream out(path, std::ios::binary); if(!out) return false; out.write(reinterpret_cast<const char*>(&hdr), sizeof(hdr)); out.write(reinterpret_cast<const char*>(t.keyLo().data()), t.capacity()*sizeof(uint64_t)); if(t.key80()) out.write(reinterpret_cast<const char*>(t.keyHi().data()), t.capacity()*sizeof(uint16_t)); out.write(reinterpret_cast<const char*>(t.meta().data()), t.capacity()*sizeof(uint8_t)); return out.good(); }

bool loadMemoFile(const std::string& path, MemoFileHeader& hdr, MemoTable& t, std::string& err){ std::ifstream in(path,std::ios::binary|std::ios::ate); if(!in){err="cannot open"; return false;} auto sz=in.tellg(); in.seekg(0); in.read(reinterpret_cast<char*>(&hdr), sizeof(hdr)); if(std::memcmp(hdr.magic,"DSMEM01",7)!=0){err="bad magic"; return false;} if((hdr.bucket_capacity&(hdr.bucket_capacity-1))!=0){err="capacity not power of two"; return false;} const bool use80=hdr.key_format==2; uint64_t expect=sizeof(MemoFileHeader)+hdr.bucket_capacity*sizeof(uint64_t)+(use80?hdr.bucket_capacity*sizeof(uint16_t):0)+hdr.bucket_capacity*sizeof(uint8_t); if(static_cast<uint64_t>(sz)!=expect){err="bad file size"; return false;} std::vector<uint64_t> lo(hdr.bucket_capacity); std::vector<uint16_t> hi(use80?hdr.bucket_capacity:0); std::vector<uint8_t> m(hdr.bucket_capacity); in.read(reinterpret_cast<char*>(lo.data()), lo.size()*sizeof(uint64_t)); if(use80) in.read(reinterpret_cast<char*>(hi.data()), hi.size()*sizeof(uint16_t)); in.read(reinterpret_cast<char*>(m.data()), m.size()); if(!in.good()){err="read fail"; return false;} t=MemoTable(use80); t.restoreRaw(hdr.bucket_capacity,hdr.entries_count,std::move(lo),std::move(hi),std::move(m)); return true; }
